mono_gc_cleanup (void)
{
#ifdef DEBUG
	g_message ("%s: cleaning up finalizer", __func__);
#endif

	if (!gc_disabled) {
		ResetEvent (shutdown_event);
		finished = TRUE;
		if (mono_thread_internal_current () != gc_thread) {
			mono_gc_finalize_notify ();
			/* Finishing the finalizer thread, so wait a little bit... */
			/* MS seems to wait for about 2 seconds */
			if (WaitForSingleObjectEx (shutdown_event, 2000, FALSE) == WAIT_TIMEOUT) {
				int ret;

				/* Set a flag which the finalizer thread can check */
				suspend_finalizers = TRUE;

				/* Try to abort the thread, in the hope that it is running managed code */
				mono_thread_internal_stop (gc_thread);

				/* Wait for it to stop */
				ret = WaitForSingleObjectEx (gc_thread->handle, 100, TRUE);

				if (ret == WAIT_TIMEOUT) {
					/* 
					 * The finalizer thread refused to die. There is not much we 
					 * can do here, since the runtime is shutting down so the 
					 * state the finalizer thread depends on will vanish.
					 */
					g_warning ("Shutting down finalizer thread timed out.");
				} else {
					/*
					 * FIXME: On unix, when the above wait returns, the thread 
					 * might still be running io-layer code, or pthreads code.
					 */
					Sleep (100);
				}

			}
		}
		gc_thread = NULL;
#ifdef HAVE_BOEHM_GC
		GC_finalizer_notifier = NULL;
#endif
	}

	DeleteCriticalSection (&handle_section);
	DeleteCriticalSection (&allocator_section);
	DeleteCriticalSection (&finalizer_mutex);
}

runarg(gs_main_instance * minst, const char *pre, const char *arg,
       const char *post, int options)
{
    int len = strlen(pre) + esc_strlen(arg) + strlen(post) + 1;
    int code;
    char *line;

    if (options & runInit) {
        code = gs_main_init2(minst);    /* Finish initialization */

        if (code < 0)
            return code;
    }
    line = (char *)gs_alloc_bytes(minst->heap, len, "runarg");
    if (line == 0) {
        lprintf("Out of memory!\n");
        return_error(e_VMerror);
    }
    strcpy(line, pre);
    esc_strcat(line, arg);
    strcat(line, post);
    /* If we're running PS from a buffer (i.e. from the "-c" option
       we don't want lib_file_open() to search the current directory
       during this call to run_string()
     */
    if ((options & runBuffer)) {
        minst->i_ctx_p->starting_arg_file = false;
    }
    else {
        minst->i_ctx_p->starting_arg_file = true;
    }
    code = run_string(minst, line, options);
    minst->i_ctx_p->starting_arg_file = false;
    gs_free_object(minst->heap, line, "runarg");
    return code;
}

static NTSTATUS smb_set_file_unix_link(connection_struct *conn,
				       struct smb_request *req,
				       const char *pdata,
				       int total_data,
				       const struct smb_filename *smb_fname)
{
	char *link_target = NULL;
	const char *newname = smb_fname->base_name;
	NTSTATUS status = NT_STATUS_OK;
	TALLOC_CTX *ctx = talloc_tos();

	/* Set a symbolic link. */
	/* Don't allow this if follow links is false. */

	if (total_data == 0) {
		return NT_STATUS_INVALID_PARAMETER;
	}

	if (!lp_symlinks(SNUM(conn))) {
		return NT_STATUS_ACCESS_DENIED;
	}

	srvstr_pull_talloc(ctx, pdata, req->flags2, &link_target, pdata,
		    total_data, STR_TERMINATE);

	if (!link_target) {
		return NT_STATUS_INVALID_PARAMETER;
	}

	/* !widelinks forces the target path to be within the share. */
	/* This means we can interpret the target as a pathname. */
	if (!lp_widelinks(SNUM(conn))) {
		char *rel_name = NULL;
		char *last_dirp = NULL;

		if (*link_target == '/') {
			/* No absolute paths allowed. */
			return NT_STATUS_ACCESS_DENIED;
		}
		rel_name = talloc_strdup(ctx,newname);
		if (!rel_name) {
			return NT_STATUS_NO_MEMORY;
		}
		last_dirp = strrchr_m(rel_name, '/');
		if (last_dirp) {
			last_dirp[1] = '\0';
		} else {
			rel_name = talloc_strdup(ctx,"./");
			if (!rel_name) {
				return NT_STATUS_NO_MEMORY;
			}
		}
		rel_name = talloc_asprintf_append(rel_name,
				"%s",
				link_target);
		if (!rel_name) {
			return NT_STATUS_NO_MEMORY;
		}

		status = check_name(conn, rel_name);
		if (!NT_STATUS_IS_OK(status)) {
			return status;
		}
	}

	DEBUG(10,("smb_set_file_unix_link: SMB_SET_FILE_UNIX_LINK doing symlink %s -> %s\n",
			newname, link_target ));

	if (SMB_VFS_SYMLINK(conn,link_target,newname) != 0) {
		return map_nt_error_from_unix(errno);
	}

	return NT_STATUS_OK;
}

ppm_load_read_header(FILE       *fp,
                     pnm_struct *img)
{
    /* PPM Headers Variable Declaration */
    gchar *ptr;
    //gchar *retval;
    gchar  header[MAX_CHARS_IN_ROW];
    gint   maxval;

    /* Check the PPM file Type P2 or P5 */
    fgets (header,MAX_CHARS_IN_ROW,fp);

    if (header[0] != ASCII_P ||
        (header[1] != PIXMAP_ASCII &&
         header[1] != PIXMAP_RAW))
      {
        g_warning ("Image is not a portable pixmap");
        return FALSE;
      }

    img->type = header[1];

    /* Check the Comments */
    fgets (header,MAX_CHARS_IN_ROW,fp);
    while(header[0] == '#')
      {
        fgets (header,MAX_CHARS_IN_ROW,fp);
      }

    /* Get Width and Height */
    img->width  = strtol (header,&ptr,0);
    img->height = atoi (ptr);
    img->numsamples = img->width * img->height * CHANNEL_COUNT;

    fgets (header,MAX_CHARS_IN_ROW,fp);
    maxval = strtol (header,&ptr,0);

    if ((maxval != 255) && (maxval != 65535))
      {
        g_warning ("Image is not an 8-bit or 16-bit portable pixmap");
        return FALSE;
      }

  switch (maxval)
    {
    case 255:
      img->bpc = sizeof (guchar);
      break;

    case 65535:
      img->bpc = sizeof (gushort);
      break;

    default:
      g_warning ("%s: Programmer stupidity error", G_STRLOC);
    }

    return TRUE;
}

int ber_get_content_length(int length)
{
	if (length > 0x81)
		return length - 4;
	else
		return length - 2;
}

set_routerstatus_from_routerinfo(routerstatus_t *rs,
                                 routerinfo_t *ri, time_t now,
                                 int naming, int listbadexits,
                                 int listbaddirs, int vote_on_hsdirs)
{
  int unstable_version =
    !tor_version_as_new_as(ri->platform,"0.1.1.16-rc-cvs");
  memset(rs, 0, sizeof(routerstatus_t));

  rs->is_authority =
    router_digest_is_trusted_dir(ri->cache_info.identity_digest);

  /* Already set by compute_performance_thresholds. */
  rs->is_exit = ri->is_exit;
  rs->is_stable = ri->is_stable =
    router_is_active(ri, now) &&
    !dirserv_thinks_router_is_unreliable(now, ri, 1, 0) &&
    !unstable_version;
  rs->is_fast = ri->is_fast =
    router_is_active(ri, now) &&
    !dirserv_thinks_router_is_unreliable(now, ri, 0, 1);
  rs->is_running = ri->is_running; /* computed above */

  if (naming) {
    uint32_t name_status = dirserv_get_name_status(
                         ri->cache_info.identity_digest, ri->nickname);
    rs->is_named = (naming && (name_status & FP_NAMED)) ? 1 : 0;
    rs->is_unnamed = (naming && (name_status & FP_UNNAMED)) ? 1 : 0;
  }
  rs->is_valid = ri->is_valid;

  if (rs->is_fast &&
      (router_get_advertised_bandwidth(ri) >= BANDWIDTH_TO_GUARANTEE_GUARD ||
       router_get_advertised_bandwidth(ri) >=
                              MIN(guard_bandwidth_including_exits,
                                  guard_bandwidth_excluding_exits))) {
    long tk = rep_hist_get_weighted_time_known(
                                      ri->cache_info.identity_digest, now);
    double wfu = rep_hist_get_weighted_fractional_uptime(
                                      ri->cache_info.identity_digest, now);
    rs->is_possible_guard = (wfu >= guard_wfu && tk >= guard_tk) ? 1 : 0;
  } else {
    rs->is_possible_guard = 0;
  }
  rs->is_bad_directory = listbaddirs && ri->is_bad_directory;
  rs->is_bad_exit = listbadexits && ri->is_bad_exit;
  ri->is_hs_dir = dirserv_thinks_router_is_hs_dir(ri, now);
  rs->is_hs_dir = vote_on_hsdirs && ri->is_hs_dir;
  rs->is_v2_dir = ri->dir_port != 0;

  if (!strcasecmp(ri->nickname, UNNAMED_ROUTER_NICKNAME))
    rs->is_named = rs->is_unnamed = 0;

  rs->published_on = ri->cache_info.published_on;
  memcpy(rs->identity_digest, ri->cache_info.identity_digest, DIGEST_LEN);
  memcpy(rs->descriptor_digest, ri->cache_info.signed_descriptor_digest,
         DIGEST_LEN);
  rs->addr = ri->addr;
  strlcpy(rs->nickname, ri->nickname, sizeof(rs->nickname));
  rs->or_port = ri->or_port;
  rs->dir_port = ri->dir_port;
}

write_header( FT_Error  error_code )
  {
    FT_Face      face;
    const char*  basename;

    error = FTC_Manager_LookupFace( handle->cache_manager,
                                    handle->scaler.face_id, &face );
    if ( error )
      PanicZ( "can't access font file" );

    if ( !status.header )
    {
      basename = ft_basename( handle->current_font->filepathname );

      switch ( error_code )
      {
      case FT_Err_Ok:
        sprintf( status.header_buffer, "%s %s (file `%s')", face->family_name,
                 face->style_name, basename );
        break;
      case FT_Err_Invalid_Pixel_Size:
        sprintf( status.header_buffer, "Invalid pixel size (file `%s')",
                 basename );
        break;
      case FT_Err_Invalid_PPem:
        sprintf( status.header_buffer, "Invalid ppem value (file `%s')",
                 basename );
        break;
      default:
        sprintf( status.header_buffer, "File `%s': error 0x%04x", basename,
            (FT_UShort)error_code );
        break;
      }

      status.header = status.header_buffer;
    }

    grWriteCellString( display->bitmap, 0, 0,
                       status.header, display->fore_color );

    sprintf( status.header_buffer, "at %g points, angle = %d",
             status.ptsize/64.0, status.angle );
    grWriteCellString( display->bitmap, 0, CELLSTRING_HEIGHT,
                       status.header_buffer, display->fore_color );

    grRefreshSurface( display->surface );
  }

_gnutls_asn1_get_structure_xml(ASN1_TYPE structure,
			       gnutls_datum_t * res, int detail)
{
    node_asn *p, *root;
    int k, indent = 0, len, len2, len3;
    opaque tmp[1024];
    char nname[256];
    int ret;
    gnutls_string str;

    if (res == NULL || structure == NULL) {
	gnutls_assert();
	return GNUTLS_E_INVALID_REQUEST;
    }

    _gnutls_string_init(&str, malloc, realloc, free);

    STR_APPEND(XML_HEADER);
    indent = 1;

    root = _asn1_find_node(structure, "");

    if (root == NULL) {
	gnutls_assert();
	_gnutls_string_clear(&str);
	return GNUTLS_E_INTERNAL_ERROR;
    }

    if (detail == GNUTLS_XML_SHOW_ALL)
	ret = asn1_expand_any_defined_by(_gnutls_get_pkix(), &structure);
    /* we don't need to check the error value
     * here.
     */

    if (detail == GNUTLS_XML_SHOW_ALL) {
	ret = _gnutls_x509_expand_extensions(&structure);
	if (ret < 0) {
	    gnutls_assert();
	    return ret;
	}
    }

    p = root;
    while (p) {
	if (is_node_printable(p)) {
	    for (k = 0; k < indent; k++)
		APPEND(" ", 1);

	    if ((ret = normalize_name(p, nname, sizeof(nname))) < 0) {
		_gnutls_string_clear(&str);
		gnutls_assert();
		return ret;
	    }

	    APPEND("<", 1);
	    STR_APPEND(nname);
	}

	if (is_node_printable(p)) {
	    switch (type_field(p->type)) {
	    case TYPE_DEFAULT:
		STR_APPEND(" type=\"DEFAULT\"");
		break;
	    case TYPE_NULL:
		STR_APPEND(" type=\"NULL\"");
		break;
	    case TYPE_IDENTIFIER:
		STR_APPEND(" type=\"IDENTIFIER\"");
		break;
	    case TYPE_INTEGER:
		STR_APPEND(" type=\"INTEGER\"");
		STR_APPEND(" encoding=\"HEX\"");
		break;
	    case TYPE_ENUMERATED:
		STR_APPEND(" type=\"ENUMERATED\"");
		STR_APPEND(" encoding=\"HEX\"");
		break;
	    case TYPE_TIME:
		STR_APPEND(" type=\"TIME\"");
		break;
	    case TYPE_BOOLEAN:
		STR_APPEND(" type=\"BOOLEAN\"");
		break;
	    case TYPE_SEQUENCE:
		STR_APPEND(" type=\"SEQUENCE\"");
		break;
	    case TYPE_BIT_STRING:
		STR_APPEND(" type=\"BIT STRING\"");
		STR_APPEND(" encoding=\"HEX\"");
		break;
	    case TYPE_OCTET_STRING:
		STR_APPEND(" type=\"OCTET STRING\"");
		STR_APPEND(" encoding=\"HEX\"");
		break;
	    case TYPE_SEQUENCE_OF:
		STR_APPEND(" type=\"SEQUENCE OF\"");
		break;
	    case TYPE_OBJECT_ID:
		STR_APPEND(" type=\"OBJECT ID\"");
		break;
	    case TYPE_ANY:
		STR_APPEND(" type=\"ANY\"");
		if (!p->down)
		    STR_APPEND(" encoding=\"HEX\"");
		break;
	    case TYPE_CONSTANT:{
		    ASN1_TYPE up = _asn1_find_up(p);

		    if (up && type_field(up->type) == TYPE_ANY &&
			up->left && up->left->value &&
			up->type & CONST_DEFINED_BY &&
			type_field(up->left->type) == TYPE_OBJECT_ID) {

			if (_gnutls_x509_oid_data_printable
			    (up->left->value) == 0) {
			    STR_APPEND(" encoding=\"HEX\"");
			}

		    }
		}
		break;
	    case TYPE_SET:
		STR_APPEND(" type=\"SET\"");
		break;
	    case TYPE_SET_OF:
		STR_APPEND(" type=\"SET OF\"");
		break;
	    case TYPE_CHOICE:
		STR_APPEND(" type=\"CHOICE\"");
		break;
	    case TYPE_DEFINITIONS:
		STR_APPEND(" type=\"DEFINITIONS\"");
		break;
	    default:
		break;
	    }
	}

	if (p->type == TYPE_BIT_STRING) {
	    len2 = -1;
	    len = _asn1_get_length_der(p->value, &len2);
	    snprintf(tmp, sizeof(tmp), " length=\"%i\"",
		     (len - 1) * 8 - (p->value[len2]));
	    STR_APPEND(tmp);
	}

	if (is_node_printable(p))
	    STR_APPEND(">");

	if (is_node_printable(p)) {
	    const unsigned char *value;

	    if (p->value == NULL)
		value = find_default_value(p);
	    else
		value = p->value;

	    switch (type_field(p->type)) {

	    case TYPE_DEFAULT:
		if (value)
		    STR_APPEND(value);
		break;
	    case TYPE_IDENTIFIER:
		if (value)
		    STR_APPEND(value);
		break;
	    case TYPE_INTEGER:
		if (value) {
		    len2 = -1;
		    len = _asn1_get_length_der(value, &len2);

		    for (k = 0; k < len; k++) {
			snprintf(tmp, sizeof(tmp),
				 "%02X", (value)[k + len2]);
			STR_APPEND(tmp);
		    }

		}
		break;
	    case TYPE_ENUMERATED:
		if (value) {
		    len2 = -1;
		    len = _asn1_get_length_der(value, &len2);

		    for (k = 0; k < len; k++) {
			snprintf(tmp, sizeof(tmp),
				 "%02X", (value)[k + len2]);
			STR_APPEND(tmp);
		    }
		}
		break;
	    case TYPE_TIME:
		if (value)
		    STR_APPEND(value);
		break;
	    case TYPE_BOOLEAN:
		if (value) {
		    if (value[0] == 'T') {
			STR_APPEND("TRUE");
		    } else if (value[0] == 'F') {
			STR_APPEND("FALSE");
		    }
		}
		break;
	    case TYPE_BIT_STRING:
		if (value) {
		    len2 = -1;
		    len = _asn1_get_length_der(value, &len2);

		    for (k = 1; k < len; k++) {
			snprintf(tmp, sizeof(tmp),
				 "%02X", (value)[k + len2]);
			STR_APPEND(tmp);
		    }
		}
		break;
	    case TYPE_OCTET_STRING:
		if (value) {
		    len2 = -1;
		    len = _asn1_get_length_der(value, &len2);
		    for (k = 0; k < len; k++) {
			snprintf(tmp, sizeof(tmp),
				 "%02X", (value)[k + len2]);
			STR_APPEND(tmp);
		    }
		}
		break;
	    case TYPE_OBJECT_ID:
		if (value)
		    STR_APPEND(value);
		break;
	    case TYPE_ANY:
		if (!p->down) {
		    if (value) {
			len3 = -1;
			len2 = _asn1_get_length_der(value, &len3);
			for (k = 0; k < len2; k++) {
			    snprintf(tmp, sizeof(tmp),
				     "%02X", (value)[k + len3]);
			    STR_APPEND(tmp);
			}
		    }
		}
		break;
	    case TYPE_CONSTANT:{
		    ASN1_TYPE up = _asn1_find_up(p);

		    if (up && type_field(up->type) == TYPE_ANY &&
			up->left && up->left->value &&
			up->type & CONST_DEFINED_BY &&
			type_field(up->left->type) == TYPE_OBJECT_ID) {

			len2 = _asn1_get_length_der(up->value, &len3);

			if (len2 > 0 && strcmp(p->name, "type") == 0) {
			    int len = sizeof(tmp);
			    ret =
				_gnutls_x509_oid_data2string(up->left->
							     value,
							     up->value +
							     len3, len2,
							     tmp, &len);

			    if (ret >= 0) {
				STR_APPEND(tmp);
			    }
			} else {
			    for (k = 0; k < len2; k++) {
				snprintf(tmp, sizeof(tmp),
					 "%02X", (up->value)[k + len3]);
				STR_APPEND(tmp);
			    }

			}
		    } else {
			if (value)
			    STR_APPEND(value);
		    }

		}
		break;
	    case TYPE_SET:
	    case TYPE_SET_OF:
	    case TYPE_CHOICE:
	    case TYPE_DEFINITIONS:
	    case TYPE_SEQUENCE_OF:
	    case TYPE_SEQUENCE:
	    case TYPE_NULL:
		break;
	    default:
		break;
	    }
	}

	if (p->down && is_node_printable(p)) {
	    ASN1_TYPE x;
	    p = p->down;
	    indent += 2;
	    x = p;
	    do {
		if (is_node_printable(x)) {
		    STR_APPEND("\n");
		    break;
		}
		x = x->right;
	    } while (x != NULL);
	} else if (p == root) {
	    if (is_node_printable(p)) {
		if ((ret = normalize_name(p, nname, sizeof(nname))) < 0) {
		    _gnutls_string_clear(&str);
		    gnutls_assert();
		    return ret;
		}

		APPEND("</", 2);
		STR_APPEND(nname);
		APPEND(">\n", 2);
	    }
	    p = NULL;
	    break;
	} else {
	    if (is_node_printable(p)) {
		if ((ret = normalize_name(p, nname, sizeof(nname))) < 0) {
		    _gnutls_string_clear(&str);
		    gnutls_assert();
		    return ret;
		}

		APPEND("</", 2);
		STR_APPEND(nname);
		APPEND(">\n", 2);
	    }
	    if (p->right)
		p = p->right;
	    else {
		while (1) {
		    ASN1_TYPE old_p;

		    old_p = p;

		    p = _asn1_find_up(p);
		    indent -= 2;
		    if (is_node_printable(p)) {
			if (!is_leaf(p))	/* XXX */
			    for (k = 0; k < indent; k++)
				STR_APPEND(" ");

			if ((ret =
			     normalize_name(p, nname,
					    sizeof(nname))) < 0) {
			    _gnutls_string_clear(&str);
			    gnutls_assert();
			    return ret;
			}

			APPEND("</", 2);
			STR_APPEND(nname);
			APPEND(">\n", 2);
		    }
		    if (p == root) {
			p = NULL;
			break;
		    }

		    if (p->right) {
			p = p->right;
			break;
		    }
		}
	    }
	}
    }

    STR_APPEND(XML_FOOTER);
    APPEND("\n\0", 2);

    *res = _gnutls_string2datum(&str);
    res->size -= 1;		/* null is not included in size */

    return 0;
}

static void cirrus_init_common(CirrusVGAState * s, int device_id, int is_pci)
{
    int vga_io_memory, i;
    static int inited;

    if (!inited) {
        inited = 1;
        for(i = 0;i < 256; i++)
            rop_to_index[i] = CIRRUS_ROP_NOP_INDEX; /* nop rop */
        rop_to_index[CIRRUS_ROP_0] = 0;
        rop_to_index[CIRRUS_ROP_SRC_AND_DST] = 1;
        rop_to_index[CIRRUS_ROP_NOP] = 2;
        rop_to_index[CIRRUS_ROP_SRC_AND_NOTDST] = 3;
        rop_to_index[CIRRUS_ROP_NOTDST] = 4;
        rop_to_index[CIRRUS_ROP_SRC] = 5;
        rop_to_index[CIRRUS_ROP_1] = 6;
        rop_to_index[CIRRUS_ROP_NOTSRC_AND_DST] = 7;
        rop_to_index[CIRRUS_ROP_SRC_XOR_DST] = 8;
        rop_to_index[CIRRUS_ROP_SRC_OR_DST] = 9;
        rop_to_index[CIRRUS_ROP_NOTSRC_OR_NOTDST] = 10;
        rop_to_index[CIRRUS_ROP_SRC_NOTXOR_DST] = 11;
        rop_to_index[CIRRUS_ROP_SRC_OR_NOTDST] = 12;
        rop_to_index[CIRRUS_ROP_NOTSRC] = 13;
        rop_to_index[CIRRUS_ROP_NOTSRC_OR_DST] = 14;
        rop_to_index[CIRRUS_ROP_NOTSRC_AND_NOTDST] = 15;
    }

    register_ioport_write(0x3c0, 16, 1, vga_ioport_write, s);

    register_ioport_write(0x3b4, 2, 1, vga_ioport_write, s);
    register_ioport_write(0x3d4, 2, 1, vga_ioport_write, s);
    register_ioport_write(0x3ba, 1, 1, vga_ioport_write, s);
    register_ioport_write(0x3da, 1, 1, vga_ioport_write, s);

    register_ioport_read(0x3c0, 16, 1, vga_ioport_read, s);

    register_ioport_read(0x3b4, 2, 1, vga_ioport_read, s);
    register_ioport_read(0x3d4, 2, 1, vga_ioport_read, s);
    register_ioport_read(0x3ba, 1, 1, vga_ioport_read, s);
    register_ioport_read(0x3da, 1, 1, vga_ioport_read, s);

    vga_io_memory = cpu_register_io_memory(0, cirrus_vga_mem_read,
                                           cirrus_vga_mem_write, s);
    cpu_register_physical_memory(isa_mem_base + 0x000a0000, 0x20000,
                                 vga_io_memory);

    s->sr[0x06] = 0x0f;
    if (device_id == CIRRUS_ID_CLGD5446) {
        /* 4MB 64 bit memory config, always PCI */
        s->sr[0x1F] = 0x2d;		// MemClock
        s->gr[0x18] = 0x0f;             // fastest memory configuration
#if 1
        s->sr[0x0f] = 0x98;
        s->sr[0x17] = 0x20;
        s->sr[0x15] = 0x04; /* memory size, 3=2MB, 4=4MB */
        s->real_vram_size = 4096 * 1024;
#else
        s->sr[0x0f] = 0x18;
        s->sr[0x17] = 0x20;
        s->sr[0x15] = 0x03; /* memory size, 3=2MB, 4=4MB */
        s->real_vram_size = 2048 * 1024;
#endif
    } else {
        s->sr[0x1F] = 0x22;		// MemClock
        s->sr[0x0F] = CIRRUS_MEMSIZE_2M;
        if (is_pci)
            s->sr[0x17] = CIRRUS_BUSTYPE_PCI;
        else
            s->sr[0x17] = CIRRUS_BUSTYPE_ISA;
        s->real_vram_size = 2048 * 1024;
        s->sr[0x15] = 0x03; /* memory size, 3=2MB, 4=4MB */
    }
    s->cr[0x27] = device_id;

    /* Win2K seems to assume that the pattern buffer is at 0xff
       initially ! */
    memset(s->vram_ptr, 0xff, s->real_vram_size);

    s->cirrus_hidden_dac_lockindex = 5;
    s->cirrus_hidden_dac_data = 0;

    /* I/O handler for LFB */
    s->cirrus_linear_io_addr =
	cpu_register_io_memory(0, cirrus_linear_read, cirrus_linear_write,
			       s);
    s->cirrus_linear_write = cpu_get_io_memory_write(s->cirrus_linear_io_addr);

    /* I/O handler for LFB */
    s->cirrus_linear_bitblt_io_addr =
	cpu_register_io_memory(0, cirrus_linear_bitblt_read, cirrus_linear_bitblt_write,
			       s);

    /* I/O handler for memory-mapped I/O */
    s->cirrus_mmio_io_addr =
	cpu_register_io_memory(0, cirrus_mmio_read, cirrus_mmio_write, s);

    /* XXX: s->vram_size must be a power of two */
    s->cirrus_addr_mask = s->real_vram_size - 1;
    s->linear_mmio_mask = s->real_vram_size - 256;

    s->get_bpp = cirrus_get_bpp;
    s->get_offsets = cirrus_get_offsets;
    s->get_resolution = cirrus_get_resolution;
    s->cursor_invalidate = cirrus_cursor_invalidate;
    s->cursor_draw_line = cirrus_cursor_draw_line;

    register_savevm("cirrus_vga", 0, 2, cirrus_vga_save, cirrus_vga_load, s);
}

int kvm_iommu_unmap_guest(struct kvm *kvm)
{
	struct iommu_domain *domain = kvm->arch.iommu_domain;

	/* check if iommu exists and in use */
	if (!domain)
		return 0;

	kvm_iommu_unmap_memslots(kvm);
	iommu_domain_free(domain);
	return 0;
}

hb_buffer_duplicate_out_buffer( HB_Buffer buffer )
{
  if ( !buffer->alt_string )
    {
      HB_Error error;

      if ( ALLOC_ARRAY( buffer->alt_string, buffer->allocated, HB_GlyphItemRec ) )
	return error;
    }

  buffer->out_string = buffer->alt_string;
  memcpy( buffer->out_string, buffer->in_string, buffer->out_length * sizeof (buffer->out_string[0]) );
  buffer->separate_out = TRUE;

  return HB_Err_Ok;
}

static int usb_host_handle_control(USBHostDevice *s, USBPacket *p)
{
    struct usbdevfs_urb *urb;
    AsyncURB *aurb;
    int ret, value, index;

    /* 
     * Process certain standard device requests.
     * These are infrequent and are processed synchronously.
     */
    value = le16_to_cpu(s->ctrl.req.wValue);
    index = le16_to_cpu(s->ctrl.req.wIndex);

    dprintf("husb: ctrl type 0x%x req 0x%x val 0x%x index %u len %u\n",
        s->ctrl.req.bRequestType, s->ctrl.req.bRequest, value, index, 
        s->ctrl.len);

    if (s->ctrl.req.bRequestType == 0) {
        switch (s->ctrl.req.bRequest) {
        case USB_REQ_SET_ADDRESS:
            return usb_host_set_address(s, value);

        case USB_REQ_SET_CONFIGURATION:
            return usb_host_set_config(s, value & 0xff);
        }
    }

    if (s->ctrl.req.bRequestType == 1 &&
                  s->ctrl.req.bRequest == USB_REQ_SET_INTERFACE)
        return usb_host_set_interface(s, index, value);

    /* The rest are asynchronous */

    aurb = async_alloc();
    aurb->hdev   = s;
    aurb->packet = p;

    /* 
     * Setup ctrl transfer.
     *
     * s->ctrl is layed out such that data buffer immediately follows
     * 'req' struct which is exactly what usbdevfs expects.
     */ 
    urb = &aurb->urb;

    urb->type     = USBDEVFS_URB_TYPE_CONTROL;
    urb->endpoint = p->devep;

    urb->buffer        = &s->ctrl.req;
    urb->buffer_length = 8 + s->ctrl.len;

    urb->usercontext = s;

    ret = ioctl(s->fd, USBDEVFS_SUBMITURB, urb);

    dprintf("husb: submit ctrl. len %u aurb %p\n", urb->buffer_length, aurb);

    if (ret < 0) {
        dprintf("husb: submit failed. errno %d\n", errno);
        async_free(aurb);

        switch(errno) {
        case ETIMEDOUT:
            return USB_RET_NAK;
        case EPIPE:
        default:
            return USB_RET_STALL;
        }
    }

    usb_defer_packet(p, async_cancel, aurb);
    return USB_RET_ASYNC;
}

static void cirrus_linear_bitblt_writel(void *opaque, target_phys_addr_t addr,
				 uint32_t val)
{
#ifdef TARGET_WORDS_BIGENDIAN
    cirrus_linear_bitblt_writeb(opaque, addr, (val >> 24) & 0xff);
    cirrus_linear_bitblt_writeb(opaque, addr + 1, (val >> 16) & 0xff);
    cirrus_linear_bitblt_writeb(opaque, addr + 2, (val >> 8) & 0xff);
    cirrus_linear_bitblt_writeb(opaque, addr + 3, val & 0xff);
#else
    cirrus_linear_bitblt_writeb(opaque, addr, val & 0xff);
    cirrus_linear_bitblt_writeb(opaque, addr + 1, (val >> 8) & 0xff);
    cirrus_linear_bitblt_writeb(opaque, addr + 2, (val >> 16) & 0xff);
    cirrus_linear_bitblt_writeb(opaque, addr + 3, (val >> 24) & 0xff);
#endif
}

